import React, { useEffect } from 'react';
import AppShell from './components/AppShell';
import ErrorBoundary from './components/ErrorBoundary';
import SimpleMapTest from './components/SimpleMapTest';
import MapDebug from './components/MapDebug';

function App() {
  useEffect(() => {
    // Initialize app
    console.log('Trek.IQ Application initialized');
  }, []);

  // Switch back to full application now that map is working
  const useSimpleMapTest = false;
  const useMapDebug = false;

  return (
    <ErrorBoundary>
      {useMapDebug ? <MapDebug /> : useSimpleMapTest ? <SimpleMapTest /> : <AppShell />}
    </ErrorBoundary>
  );
}

export default App;
